import "server-only";
import fs from "node:fs";
import path from "node:path";
import { siteLayoutConfig } from "@/config/site-layout";
import {
  EMPTY_PLUGIN_INDEX,
  type PluginIndex,
  type PluginItem,
  pluginIndexSchema,
} from "@/lib/plugin-schema";
import type { PluginMarketplace } from "@/lib/plugin-install";
import { skillsRepo } from "@/lib/skills";

export type { PluginItem } from "@/lib/plugin-schema";

// Generated by `pnpm plugins:index` (also run by `pnpm skills:index` and `pnpm build`) and not
// tracked in Git. Dev and unit tests render a missing or invalid file as "no plugins"; a
// production build throws instead, so the site never ships an empty /plugins page by accident.
const INDEX_FILE = path.join(process.cwd(), "src/generated/plugins-index.json");

function loadIndex(): PluginIndex {
  let problem: string;
  try {
    const parsed = pluginIndexSchema.safeParse(
      JSON.parse(fs.readFileSync(INDEX_FILE, "utf8")),
    );
    if (parsed.success) return parsed.data;
    problem = `does not match the plugin index schema (${parsed.error.message})`;
  } catch (error) {
    problem = `cannot be read (${String(error)})`;
  }
  if (process.env.NODE_ENV === "production")
    throw new Error(
      `Plugin index ${INDEX_FILE} ${problem}. Run \`pnpm run plugins:index\` in apps/web before building.`,
    );
  return EMPTY_PLUGIN_INDEX;
}

// Production reads the file once; dev re-reads it so `pnpm plugins:index` shows up without a restart.
const cachedIndex = loadIndex();
const currentIndex = () =>
  process.env.NODE_ENV === "development" ? loadIndex() : cachedIndex;
const repoName = skillsRepo.split("/")[1];

/** `claude plugin install <name> --marketplace <source>`; `<name>@<name>` addresses installed plugins. */
export const pluginMarketplace: PluginMarketplace = {
  source: `${siteLayoutConfig.ownerDisplay}/${repoName}`,
  name: cachedIndex.marketplace || repoName,
};

export function getAllPlugins(): PluginItem[] {
  return currentIndex().plugins;
}

export function getPluginBySlug(slug: string): PluginItem | null {
  return currentIndex().plugins.find((plugin) => plugin.name === slug) ?? null;
}

export function getPluginSourceUrl(
  plugin: Pick<PluginItem, "sourcePath">,
): string {
  return `https://github.com/${skillsRepo}/tree/main/${plugin.sourcePath}`;
}

/**
 * README links are relative to the plugin folder; point them at GitHub so they
 * do not 404 on the site. Absolute URLs, anchors and mailto links are kept.
 */
export function resolvePluginReadmeLinks(
  markdown: string,
  plugin: Pick<PluginItem, "sourcePath">,
): string {
  return markdown.replace(
    /(!?\[[^\]]*\]\()([^)\s]+)(\))/g,
    (match, open: string, href: string, close: string) => {
      if (/^(?:[a-z][a-z0-9+.-]*:|#|\/)/i.test(href)) return match;
      const target = path.posix.normalize(
        path.posix.join(plugin.sourcePath, href),
      );
      const kind = open.startsWith("!") ? "raw" : "blob";
      return `${open}https://github.com/${skillsRepo}/${kind}/main/${target}${close}`;
    },
  );
}
